    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # dp[a * 3 + b] stores the minimum cost to paint the pairs up to the current depth
        # with the left house colored 'a' and the right house colored 'b'.
        dp = [float('inf')] * 9
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[a * 3 + b] = cost[0][a] + cost[n - 1][b]

        # Precompute the valid state transitions.
        # For each valid current color pair (a2, b2), we find all valid previous color pairs (a, b)
        # such that a != a2 (adjacent left), b != b2 (adjacent right), and a != b (equidistant).
        transitions = []
        for a2 in range(3):
            for b2 in range(3):
                if a2 != b2:
                    curr = a2 * 3 + b2
                    prevs = []
                    for a in range(3):
                        if a != a2:
                            for b in range(3):
                                if b != b2 and a != b:
                                    prevs.append(a * 3 + b)
                    # prevs will always contain exactly 3 valid previous states
                    transitions.append((curr, a2, b2, prevs[0], prevs[1], prevs[2]))

        half = n // 2
        for i in range(1, half):
            new_dp = [float('inf')] * 9
            c_left = cost[i]
            c_right = cost[n - 1 - i]

            for curr, a2, b2, p1, p2, p3 in transitions:
                # Find the minimum cost among the valid previous states
                best = dp[p1]
                if dp[p2] < best: best = dp[p2]
                if dp[p3] < best: best = dp[p3]

                # Update the new dp array with the optimal previous configuration + current painting cost
                new_dp[curr] = best + c_left[a2] + c_right[b2]

